import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/solicitacao.dart';
import '../services/solicitacao_service.dart';
import '../services/mensagem_service.dart';
import '../widgets/async_ui.dart';
class PedidosPage extends StatefulWidget {final String modo;const PedidosPage({super.key,required this.modo});@override State<PedidosPage> createState()=>_PedidosPageState();}
class _PedidosPageState extends State<PedidosPage>{final service=SolicitacaoService();late final Stream<List<Solicitacao>> stream;String filtro='Todos',busca='';final ocupados=<String>{};
 @override void initState(){super.initState();stream=service.listar(widget.modo);}
 Future<void> acao(Solicitacao s,String destino,bool transacao) async {if(ocupados.contains(s.id)||!await confirmar(context,'Confirmar alteração para $destino?')||!mounted)return;setState(()=>ocupados.add(s.id));await executar(context,()=>transacao?service.transicao(s.id,destino):service.simples(s.id,destino));if(mounted)setState(()=>ocupados.remove(s.id));}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.modo=='enviadas'?'Minhas solicitações':widget.modo=='recebidas'?'Solicitações recebidas':'Gerenciar adoções')),body:StreamBuilder<List<Solicitacao>>(stream:stream,builder:(context,s){if(s.hasError)return erro(s.error);if(!s.hasData)return espera();final lista=s.data!.where((p)=>(filtro=='Todos'||p.status==filtro)&&('${p.animalNome} ${p.dados['adotanteNome']}'.toLowerCase().contains(busca.toLowerCase()))).toList();return Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(decoration:const InputDecoration(labelText:'Buscar animal ou interessado'),onChanged:(v)=>setState(()=>busca=v))),DropdownButton<String>(value:filtro,items:['Todos','pendente','aceita','recusada','cancelada','concluida'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>filtro=v!)),Text('${lista.length} solicitações'),Expanded(child:ListView.builder(itemCount:lista.length,itemBuilder:(context,i){final p=lista[i];final livre=!ocupados.contains(p.id);Widget botao(String titulo,String destino,bool transacao)=>TextButton(onPressed:livre?()=>acao(p,destino,transacao):null,child:Text(titulo));return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p.animalNome,style:Theme.of(context).textTheme.titleLarge),Text('Interessado: ${p.dados['adotanteNome']}'),Text('Status: ${p.status}'),Text('${p.dados['mensagem']}'),if(p.status=='pendente')const Text('A disponibilidade do animal pode mudar.'),Wrap(children:[if(widget.modo=='enviadas'&&p.status=='pendente')botao('Cancelar','cancelada',false),if(widget.modo=='recebidas'&&p.status=='pendente')...[botao('Aceitar','aceita',true),botao('Recusar','recusada',false)],if(widget.modo=='recebidas'&&p.status=='aceita')...[botao('Concluir adoção','concluida',true),botao('Desfazer aceite','cancelada',true)],if(widget.modo!='admin'&&['aceita','concluida'].contains(p.status))TextButton(onPressed:()=>abrir(context,ChatPage(pedido:p)),child:const Text('Conversar / histórico'))])])));}))]);}));
}
class ChatPage extends StatefulWidget {final Solicitacao pedido;const ChatPage({super.key,required this.pedido});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final service=MensagemService();final texto=TextEditingController();bool ocupado=false;late final Stream<QuerySnapshot<Map<String,dynamic>>> mensagens;late final Stream<DocumentSnapshot<Map<String,dynamic>>> pedido;
 @override void initState(){super.initState();mensagens=service.listar(widget.pedido.id);pedido=FirebaseFirestore.instance.collection('solicitacoes').doc(widget.pedido.id).snapshots();}
 @override void dispose(){texto.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('Adoção: ${widget.pedido.animalNome}')),body:StreamBuilder<DocumentSnapshot<Map<String,dynamic>>>(stream:pedido,builder:(context,s){if(s.hasError)return erro(s.error);if(!s.hasData)return espera();final status=s.data?.data()?['status'];if(!['aceita','concluida'].contains(status))return const Center(child:Text('Conversa encerrada'));return Column(children:[Text(status=='aceita'?'Conversa privada':'Histórico somente para leitura'),Expanded(child:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:mensagens,builder:(context,m){if(m.hasError)return erro(m.error);if(!m.hasData)return espera();return ListView.builder(reverse:true,itemCount:m.data!.docs.length,itemBuilder:(context,i){final d=m.data!.docs[i].data();final minha=d['remetenteId']==service.uid;return Align(alignment:minha?Alignment.centerRight:Alignment.centerLeft,child:Card(color:minha?const Color(0xffddece2):Colors.white,child:Padding(padding:const EdgeInsets.all(12),child:Text(d['texto']??''))));});})),if(status=='aceita')SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:texto,enabled:!ocupado,maxLength:500,decoration:const InputDecoration(hintText:'Mensagem'))),IconButton(onPressed:ocupado?null:()async{if(texto.text.trim().isEmpty)return;setState(()=>ocupado=true);await executar(context,()async{await service.enviar(widget.pedido.id,texto.text);texto.clear();});if(mounted)setState(()=>ocupado=false);},icon:const Icon(Icons.send))]))) ]);}));
}
